; Screen and colour RAM fill
; $730b-$7338

; Clears $0400-$0bff (both screens) to 0 and sets $d3 = 4.
clear_screens
        lda #>screen_a
        sta map_ptr_hi
        ldy #<screen_a
        sty map_ptr
        lda #$04
        sta zp_count
clear_screens_page
        lda #$00
clear_screens_loop
        sta (map_ptr),y
        iny
        bne clear_screens_loop
        inc map_ptr_hi
        lda map_ptr_hi
        cmp #$0c
        bne clear_screens_page
        rts
; Fills colour RAM $d800-$dbff with the colour in A.
fill_colour_ram
        ldy #$00
fill_colour_ram_loop
        sta $d800,y
        sta $d900,y
        sta $da00,y
        sta $db00,y
        iny
        bne fill_colour_ram_loop
